def solve(arr, n):
    # Count the number of inversions of two types
    # Type 1: (i, j) where i < j and arr[i] > arr[j]
    # Type 2: (i, j) where i < j and arr[i] < arr[j]
    # We need to check if the counts are the same

    # Count inversions of type 1
    inv1 = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                inv1 += 1

    # Count inversions of type 2
    inv2 = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] < arr[j]:
                inv2 += 1

    # Check if the counts are the same
    return inv1 == inv2
