def swap_count(s):
    # Initialize a stack to keep track of the indices of the opening brackets
    stack = []
    # Initialize a variable to count the number of swaps
    swaps = 0

    # Iterate through the string
    for i, char in enumerate(s):
        if char == '[':
            stack.append(i)
        elif char == ']':
            # If the stack is not empty, we can swap
            if stack:
                # Pop the last opening bracket from the stack
                j = stack.pop()
                # If the current index is not the same as the index of the opening bracket, we need to swap
                if i != j:
                    swaps += 1
    return swaps
```

