def find_min(arr, start, end):
    if start > end:
        return arr[start]
    if start == end:
        return arr[start]
    mid = (start + end) // 2
    if arr[mid] < arr[end]:
        return find_min(arr, start, mid)
    else:
        return find_min(arr, mid + 1, end)
```

